from z3 import *
# Declarations
houses_sort, (h1, h3, h5, h7, h2, h4, h6, h8) = EnumSort('houses', ['h1', 'h3', 'h5', 'h7', 'h2', 'h4', 'h6', 'h8'])
styles_sort, (ranch, split_level, tudor) = EnumSort('styles', ['ranch', 'split_level', 'tudor'])
houses = [h1, h3, h5, h7, h2, h4, h6, h8]
styles = [ranch, split_level, tudor]
style_of = Function('style_of', houses_sort, styles_sort)

# Constraints
pre_conditions = []
# CONSTRAINT: Adjacent houses are of different styles
pre_conditions.append(style_of(h1) != style_of(h3))
pre_conditions.append(style_of(h3) != style_of(h5))
pre_conditions.append(style_of(h5) != style_of(h7))
pre_conditions.append(style_of(h2) != style_of(h4))
pre_conditions.append(style_of(h4) != style_of(h6))
pre_conditions.append(style_of(h6) != style_of(h8))
# CONSTRAINT: No split-level house faces another split-level house
pre_conditions.append(Not(And(style_of(h1) == split_level, style_of(h2) == split_level)))
pre_conditions.append(Not(And(style_of(h3) == split_level, style_of(h4) == split_level)))
pre_conditions.append(Not(And(style_of(h5) == split_level, style_of(h6) == split_level)))
pre_conditions.append(Not(And(style_of(h7) == split_level, style_of(h8) == split_level)))
# CONSTRAINT: Every ranch house has at least one Tudor house adjacent to it
def has_tudor_adjacent(h):
    if h == h1:
        return style_of(h3) == tudor
    elif h == h3:
        return Or(style_of(h1) == tudor, style_of(h5) == tudor)
    elif h == h5:
        return Or(style_of(h3) == tudor, style_of(h7) == tudor)
    elif h == h7:
        return style_of(h5) == tudor
    elif h == h2:
        return Or(style_of(h4) == tudor)
    elif h == h4:
        return Or(style_of(h2) == tudor, style_of(h6) == tudor)
    elif h == h6:
        return Or(style_of(h4) == tudor, style_of(h8) == tudor)
    elif h == h8:
        return Or(style_of(h6) == tudor)
    else:
        return False

for h in houses:
    pre_conditions.append(Implies(style_of(h) == ranch, has_tudor_adjacent(h)))
# CONSTRAINT: House 3 is a ranch house
pre_conditions.append(style_of(h3) == ranch)
# CONSTRAINT: House 6 is a split-level house
pre_conditions.append(style_of(h6) == split_level)
# Additional constraint: House 4 is a Tudor house
pre_conditions.append(style_of(h4) == tudor)

# Question: If house 4 is a Tudor house, then it could be true that house
def is_sat(option_constraints):
    solver = Solver()
    solver.add(pre_conditions)
    solver.add(option_constraints)
    return solver.check() == sat
# OPTION A) 1 is a Tudor house
if is_sat(style_of(h1) == tudor): print('A')
# OPTION B) 2 is a Tudor house
if is_sat(style_of(h2) == tudor): print('B')
# OPTION C) 5 is a ranch house
if is_sat(style_of(h5) == ranch): print('C')
# OPTION D) 7 is a Tudor house
if is_sat(style_of(h7) == tudor): print('D')
# OPTION E) 8 is a ranch house
if is_sat(style_of(h8) == ranch): print('E')
